import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        // Key sorts by (value, index); values are shifted to be non-negative.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = ((r.nextLong() + 1_000_000_000L) << 18) | i;
        Arrays.sort(key);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append((key[i] & ((1 << 18) - 1)) + 1);
        }
        System.out.println(sb);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"cmp"
	"os"
	"slices"
	"strconv"
)

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	// Sort indices by (value, index).
	slices.SortFunc(order, func(i, j int) int {
		if a[i] != a[j] {
			return cmp.Compare(a[i], a[j])
		}
		return cmp.Compare(i, j)
	})
	out := make([]byte, 0, 8*n)
	for i, idx := range order {
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(idx+1), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
